const msg = raw.message;
if (msg && msg.chat) {
  const text = String(msg.text || msg.caption || '').trim();
  const em = text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
  const f = msg.from || {};
  const name = [f.first_name, f.last_name].filter(Boolean).join(' ') || f.username || 'Client';
  return [{ json: { body: { from: em ? em[0] : '', name: name, message: text, source: 'telegram', telegram_chat_id: String(msg.chat.id) } } }];
}
const fbv = raw.value || (raw.entry && raw.entry[0] && ((raw.entry[0].changes && raw.entry[0].changes[0] && raw.entry[0].changes[0].value) || (raw.entry[0].messaging && raw.entry[0].messaging[0]))) || null;
if (fbv && (raw.field || raw.object || raw.entry)) {
  const fm = fbv.message;
  const ftext = String((fm && typeof fm === 'object' ? fm.text : fm) || fbv.text || '').trim();
  const fem = ftext.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
  const sender = fbv.sender || fbv.from || {};
  const fname = sender.name || 'Client';
  return [{ json: { body: { from: fem ? fem[0] : '', name: fname, message: ftext, source: 'facebook', facebook_sender_id: String(sender.id || '') } } }];
}
return [{ json: raw }];

