const ctx = $('Build Context (Settings + Last 5 Feedback)').first().json;
const requirements = $('AI Requirements Analyst').first().json.output || {};
const p = $input.first().json.output || {};
const warnings = [];
const DISCLOSURE = 'This service uses an AI-assisted workflow with human review.';

let numPieces = Number(p.num_pieces);
if (!isFinite(numPieces) || numPieces <= 0) numPieces = Number(requirements.num_pieces) || 0;
let wordsPer = Number(p.words_per_piece);
if (!isFinite(wordsPer) || wordsPer <= 0) wordsPer = Number(requirements.words_per_piece) || 0;
const expectedTotal = numPieces * wordsPer;
let totalWords = Number(p.total_words);
if (!isFinite(totalWords) || totalWords !== expectedTotal) {
  warnings.push('total_words ' + p.total_words + ' did not match num_pieces x words_per_piece (' + expectedTotal + ') - corrected');
  totalWords = expectedTotal;
}

let price = Number(p.price);
const aiPrice = isFinite(price) ? price : null;
const minimumPrice = ctx.rate_per_post * totalWords / 500;
const floorPrice = Math.ceil(Math.max(ctx.min_price, minimumPrice * 0.9));
if (!isFinite(price)) { price = floorPrice; warnings.push('Price was missing/invalid - set to ' + floorPrice); }
else if (price < floorPrice) { warnings.push('Price ' + price + ' was below the allowed minimum - raised to ' + floorPrice + ' (min_price ' + ctx.min_price + ', rate-based minimum ' + Math.round(minimumPrice) + ')'); price = floorPrice; }

let deadline = Number(p.deadline_days);
if (!isFinite(deadline)) { deadline = ctx.max_deadline_days; warnings.push('Deadline missing/invalid - set to max_deadline_days ' + ctx.max_deadline_days); }
if (deadline > ctx.max_deadline_days) { warnings.push('Deadline ' + deadline + ' days exceeded max - reduced to ' + ctx.max_deadline_days); deadline = ctx.max_deadline_days; }

let revisions = Number(p.revisions);
if (!isFinite(revisions)) { revisions = ctx.max_revisions; warnings.push('Revisions missing/invalid - set to max_revisions ' + ctx.max_revisions); }
if (revisions > ctx.max_revisions) { warnings.push('Revisions ' + revisions + ' exceeded max - reduced to ' + ctx.max_revisions); revisions = ctx.max_revisions; }

if (requirements.needs_extra_review === true) warnings.push('Sensitive topic: check facts carefully');

let emailText = String(p.email_text || '');
if (emailText.indexOf(DISCLOSURE) < 0) emailText = emailText.trim() + '\n\n' + DISCLOSURE;

return [{ json: {
  project_id: ctx.project_id,
  client_email: ctx.client_email,
  client_name: ctx.client_name,
  message: ctx.message,
  created_at: ctx.created_at,
  requirements: requirements,
  ai_price: aiPrice,
  proposal: {
    scope: Array.isArray(p.scope) ? p.scope : [],
    content_type: String(p.content_type || requirements.content_type || ''),
    num_pieces: numPieces,
    words_per_piece: wordsPer,
    total_words: totalWords,
    price: price,
    deadline_days: deadline,
    revisions: revisions,
    email_text: emailText,
    internal_note: String(p.internal_note || ''),
  },
  warnings: warnings,
} }];

const g = $('Guardrail Check').first().json;
const r = $input.first().json || {};
const d = (r.data && typeof r.data === 'object') ? r.data : r;
const decision = d.decision ? String(d.decision) : 'TIMEOUT';
const aiPrice = g.proposal.price;
let finalPrice = Number(d.final_price);
if (!isFinite(finalPrice) || finalPrice <= 0) finalPrice = aiPrice;
const note = d.note ? String(d.note) : '';
const edit = finalPrice !== aiPrice ? 'Price changed from ' + aiPrice + ' to ' + finalPrice : 'Price unchanged (' + aiPrice + ')';
const esc = function (t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const p = g.proposal;
const html = '<p>' + esc(p.email_text).replace(/\n/g, '<br>') + '</p>'
  + '<hr><p><b>Proposal summary</b></p><ul>'
  + p.scope.map(function (s) { return '<li>' + esc(s) + '</li>'; }).join('')
  + '</ul><p><b>Content:</b> ' + esc(p.content_type) + ', ' + p.num_pieces + ' x ' + p.words_per_piece + ' words (total ' + p.total_words + ' words)<br><b>Price (PKR):</b> ' + finalPrice + '<br><b>Delivery time:</b> ' + p.deadline_days + ' days<br><b>Revisions included:</b> ' + p.revisions + '</p>'
  + '<hr><p><small>This service uses an AI-assisted workflow with human review.</small></p>';
return [{ json: {
  decision: decision,
  timed_out: decision === 'TIMEOUT',
  final_price: finalPrice,
  note: note,
  human_edit: edit + (note ? '. Note: ' + note : ''),
  proposal_email_html: html,
  proposal_json_final: JSON.stringify(Object.assign({}, p, { price: finalPrice })),
  timestamp: new Date().toISOString(),
} }];

