const st = $('Round State').first().json;
const g = $('Guardrail Check').first().json;
const req = g.requirements || {};
const prop = g.proposal || {};
const pieces = (($input.first().json.output || {}).pieces) || [];
const expectedPieces = Number(prop.num_pieces) || Number(req.num_pieces) || 0;
const target = Number(prop.words_per_piece) || Number(req.words_per_piece) || 0;
const keywords = Array.isArray(req.keywords) ? req.keywords.filter(function (k) { return k && String(k).trim(); }) : [];
const esc = function (t) { return String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const countWords = function (t) { return String(t || '').trim().split(/\s+/).filter(function (w) { return w.length > 0; }).length; };

const counts = pieces.map(function (p) { return countWords(p.content); });
const total = counts.reduce(function (a, b) { return a + b; }, 0);
const avg = counts.length ? Math.round(total / counts.length) : 0;
const lower = Math.floor(target * 0.9);
const upper = Math.ceil(target * 1.1);
const issues = [];

if (pieces.length !== expectedPieces) issues.push('Piece count issue: expected ' + expectedPieces + ' pieces but got ' + pieces.length);
counts.forEach(function (c, i) {
  if (c === 0) issues.push('Piece ' + (i + 1) + ' is empty');
  else if (target > 0 && (c < lower || c > upper)) issues.push('Word count issue: piece ' + (i + 1) + ' has ' + c + ' words (target ' + target + ', allowed ' + lower + '-' + upper + ')');
});
if (target > 0 && counts.length && (avg < lower || avg > upper)) issues.push('Word count issue: average is ' + avg + ' words per piece (target ' + target + ', allowed ' + lower + '-' + upper + ')');

const allText = pieces.map(function (p) { return (p.title || '') + ' ' + (p.content || ''); }).join(' ').toLowerCase();
const missingKw = keywords.filter(function (k) { return allText.indexOf(String(k).toLowerCase()) < 0; });
if (missingKw.length) issues.push('Keywords not found in the text: ' + missingKw.join(', '));

const report = 'Pieces: ' + pieces.length + ' of ' + expectedPieces + ' requested. Words per piece: ' + (counts.length ? counts.join(', ') : 'n/a') + '. Average: ' + avg + ' (target ' + target + ', allowed ' + lower + '-' + upper + '). Total words: ' + total + ' (agreed ' + (expectedPieces * target) + '). Keywords: ' + (keywords.length ? (keywords.length - missingKw.length) + ' of ' + keywords.length + ' found' : 'none requested') + '.';

const sep = '\n\n----------------------------------------\n\n';
let text = pieces.map(function (p, i) {
  return 'PIECE ' + (i + 1) + ' of ' + pieces.length + '\nTitle: ' + (p.title || '') + '\nMeta description: ' + (p.meta_description || '') + '\n\n' + (p.content || '') + '\n\nKeywords used: ' + (Array.isArray(p.keywords_used) ? p.keywords_used.join(', ') : '');
}).join(sep);
if (text.length > 45000) text = text.slice(0, 44900) + '\n\n[TRUNCATED to fit the Google Sheets cell limit]';
const html = pieces.map(function (p, i) {
  return '<h3>Piece ' + (i + 1) + ': ' + esc(p.title) + '</h3><p><i>Meta description: ' + esc(p.meta_description) + '</i></p><p>' + esc(p.content).replace(/\n/g, '<br>') + '</p>';
}).join('<hr>');

return [{ json: {
  pieces: pieces,
  piece_count: pieces.length,
  total_words: total,
  average_words: avg,
  deliverable_text: text,
  deliverable_html: html,
  word_count_report: report,
  automatic_issues: issues,
  retry_count: st.retry_count,
  feedback_from_qa: st.feedback_from_qa,
  gate2_rounds: st.gate2_rounds,
} }];

