const qa = $input.first().json.output || {};
const draft = $('Package Draft').first().json;
const g = $('Guardrail Check').first().json;
const san = function (t) { return String(t === null || t === undefined ? '' : t).replace(/[<>&*]/g, ' '); };
const auto = Array.isArray(draft.automatic_issues) ? draft.automatic_issues : [];
const qaIssues = Array.isArray(qa.issues) ? qa.issues.map(function (x) { return typeof x === 'string' ? x : JSON.stringify(x); }) : [];
const issues = qaIssues.concat(auto.filter(function (a) { return qaIssues.indexOf(a) < 0; }));
const issueText = issues.length ? issues.map(function (x) { return '- ' + san(x); }).join('\n') : 'None';
const unresolved = qa.passed !== true || auto.length > 0;
const head = [
  'GATE 2: Approve final work for delivery?',
  '',
  'Client: ' + san(g.client_name),
  'AI QA score: ' + qa.score + '/100' + (unresolved ? '  --  QA DID NOT PASS (unresolved issues after ' + draft.retry_count + ' retries)' : '  --  QA passed'),
  'QA issues:',
  issueText,
  '',
  'Word count report: ' + san(draft.word_count_report),
  '',
  'Revision rounds used so far: ' + draft.gate2_rounds + ' of 2',
  '',
  'Deliverable:',
].join('\n');
const body = san(draft.deliverable_text);
const full = head + '\n' + body;
return [{ json: {
  gate2_message: full,
  gate2_full: full,
  qa_score: qa.score,
  qa_passed: !unresolved,
  qa_issues: issues,
  word_count_report: draft.word_count_report,
  deliverable_text: draft.deliverable_text,
  deliverable_html: draft.deliverable_html,
} }];

const r = $input.first().json || {};
