return [{ json: {
  decision: decision,
  timed_out: decision === 'TIMEOUT',
  feedback: d.feedback ? String(d.feedback) : '',
  timestamp: new Date().toISOString(),
} }];

const g = $('Guardrail Check').first().json;
const g1 = $('Gate 1 - Normalize Response').first().json;
const rev = $('Prepare Gate 2 Review').first().json;
const p = g.proposal;
const esc = function (t) { return String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const date = new Date().toISOString().slice(0, 10);
const row = function (k, v) { return '<tr><td style="padding:6px;border-bottom:1px solid #ddd"><b>' + k + '</b></td><td style="padding:6px;border-bottom:1px solid #ddd">' + esc(v) + '</td></tr>'; };
const inv = '<div style="font-family:Arial,sans-serif;max-width:600px;border:1px solid #ccc;padding:20px">'
  + '<h2>Invoice</h2>'
  + '<table style="width:100%;border-collapse:collapse">'
  + row('Invoice number', g.project_id)
  + row('Client', g.client_name)
  + row('Content type', p.content_type)
  + row('Number of pieces', p.num_pieces)
  + row('Total words', p.total_words)
  + row('Revisions included', p.revisions)
  + row('Date', date)
  + '</table>'
  + '<h3>Total: PKR ' + esc(g1.final_price) + '</h3>'
  + '<p><small>AI-assisted workflow with human review</small></p></div>';
const body = '<p>Hello ' + esc(g.client_name) + ',</p><p>Your content is ready. Please find the full text and your invoice below.</p>'
  + rev.deliverable_html
  + '<hr>' + inv
  + '<hr><p>Reply to this email within 7 days for revisions (up to ' + esc(p.revisions) + ' rounds).</p>'
  + '<p><small>This service uses an AI-assisted workflow with human review.</small></p>';
return [{ json: { invoice_html: inv, delivery_html: body, subject: 'Your content is ready - ' + g.project_id } }];

